-- Rawlsing P3 logical validation queries v7. Read-only; phase-aware.
-- Q01 pre-promotion: pointer count must be 0 or 1. Post-promotion gate separately requires 1.
SELECT CASE WHEN COUNT(*)<=1 THEN 'PASS' ELSE 'FAIL' END AS q01_pointer_cardinality FROM p3_runtime_promotion_pointer;
SELECT CASE WHEN COUNT(*)=1 THEN 'PASS' ELSE 'FAIL' END AS q01b_postpromotion_pointer FROM p3_runtime_promotion_pointer;
SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM p3_runtime_promotion_pointer p WHERE NOT EXISTS (SELECT 1 FROM p3_release_status_event e WHERE e.release_id=p.promoted_release_id AND e.status='PROMOTED')) THEN 'PASS' ELSE 'FAIL' END AS q02_pointer_has_promoted_event;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q03_no_reflexive_pairs FROM p3_pair_fact_bundle WHERE left_object_id=right_object_id;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q04_proposition_graph_types FROM p3_pair_fact_bundle WHERE proposition_graph_allowed IS DISTINCT FROM (relation_type IN ('PROPOSITION_RESPONSE_IDENTITY','PROPOSITION_IDENTITY_ONLY'));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q05_no_path_authority FROM p3_pair_fact_bundle WHERE creates_endpoint_authority;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q06_one_governing_source FROM p3_pair_fact_bundle p LEFT JOIN (SELECT pair_fact_id,COUNT(*) FILTER (WHERE governing) n FROM p3_pair_fact_source_authority GROUP BY pair_fact_id) s USING(pair_fact_id) WHERE COALESCE(s.n,0)<>1;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q07_candidate_membership_unique FROM (SELECT candidate_revision_id,member_object_id,COUNT(*) n FROM p3_candidate_membership GROUP BY 1,2 HAVING COUNT(*)<>1) x;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q08_complete_pair_matrix FROM p3_candidate_revision r JOIN (SELECT candidate_revision_id,COUNT(DISTINCT member_object_id) n FROM p3_candidate_membership WHERE membership_role='PROPOSED_MEMBER' GROUP BY 1) m USING(candidate_revision_id) LEFT JOIN (SELECT candidate_revision_id,COUNT(*) n FROM p3_internal_pair_matrix GROUP BY 1) x USING(candidate_revision_id) WHERE COALESCE(x.n,0)<>(m.n*(m.n-1))/2;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q09_component_stored_counts FROM p3_candidate_component c LEFT JOIN (SELECT component_id,COUNT(*) n FROM p3_component_membership GROUP BY 1) m USING(component_id) WHERE COALESCE(m.n,0)<>c.member_count;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q10_clean_candidate_blockers FROM p3_candidate_revision r WHERE r.candidate_classification='CLEAN_CANDIDATE' AND (EXISTS (SELECT 1 FROM p3_internal_pair_matrix x WHERE x.candidate_revision_id=r.candidate_revision_id AND x.pair_state IN ('DIRECT_COLLISION','DIRECT_UNRESOLVED','SIGNATURE_CONFLICT')) OR EXISTS (SELECT 1 FROM p3_closure_obligation o WHERE o.candidate_revision_id=r.candidate_revision_id AND o.status='OPEN'));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q11_family_revision_complete FROM p3_canonical_family_revision f JOIN p3_proposition_signature s ON s.signature_id=f.canonical_signature_id LEFT JOIN (SELECT family_revision_id,COUNT(*) n FROM p3_canonical_family_membership GROUP BY 1) m USING(family_revision_id) WHERE COALESCE(m.n,0)<2 OR s.signature_status<>'COMPLETE';
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q12_rule_exclusion_present FROM p3_canonical_family_revision f WHERE NOT EXISTS (SELECT 1 FROM p3_family_exclusion e WHERE e.owner_object_id=f.canonical_family_id AND e.exclusion_type='RULE_BASED' AND e.authority_release_id=f.authority_release_id);
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q13_named_exclusions_when_needed FROM p3_adjudication_decision a WHERE a.decision_status IN ('ACCEPTED_CANONICAL','ACCEPTED_WITH_VARIANTS') AND EXISTS (SELECT 1 FROM p3_adjudication_member m WHERE m.adjudication_id=a.adjudication_id AND m.member_disposition='EXCLUDE') AND NOT EXISTS (SELECT 1 FROM p3_family_exclusion e WHERE e.owner_object_id=a.canonical_family_id AND e.exclusion_type='NAMED_MEMBER' AND e.authority_release_id=a.authority_release_id);
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q14_no_measurement_leak FROM p3_family_variant_revision WHERE value_portability_status<>'NOT_AUTHORIZED_BY_P3';
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q15_family_adjudication_consistency FROM p3_canonical_family f JOIN p3_adjudication_decision a ON a.adjudication_id=f.created_by_adjudication_id WHERE a.canonical_family_id IS DISTINCT FROM f.canonical_family_id OR a.decision_status NOT IN ('ACCEPTED_CANONICAL','ACCEPTED_WITH_VARIANTS');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q15b_no_unadjudicated_at_p3_close FROM p3_lineage_disposition WHERE disposition_status='UNADJUDICATED';
-- Release event ordinals and transition chains.
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q16_release_event_contiguous FROM (SELECT release_id,MIN(event_ordinal) mi,MAX(event_ordinal) ma,COUNT(*) n FROM p3_release_status_event GROUP BY release_id HAVING MIN(event_ordinal)<>1 OR MAX(event_ordinal)<>COUNT(*)) x;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q17_candidate_event_contiguous FROM (SELECT candidate_revision_id,MIN(event_ordinal) mi,MAX(event_ordinal) ma,COUNT(*) n FROM p3_candidate_status_event GROUP BY candidate_revision_id HAVING MIN(event_ordinal)<>1 OR MAX(event_ordinal)<>COUNT(*)) x;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q18_signature_has_twelve_fields FROM p3_proposition_signature s LEFT JOIN (SELECT signature_id,COUNT(*) n FROM p3_signature_field GROUP BY 1) f USING(signature_id) WHERE COALESCE(f.n,0)<>12;
-- Polymorphic reference type checks are generated from P3_OBJECT_REFERENCE_TYPE_CONTRACT_v7.csv.
-- Genealogy cycle, relation cardinality, release parent cycle, snapshot/change-ledger diff, and lifecycle transition checks are generated by the v24 validator because they require recursive or contract-driven queries.

-- Q19-Q25 bounded-readiness enforcement checks.
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q19_identity_contract_complete FROM p3_object_registry o LEFT JOIN p3_identity_key_contract c ON c.object_type=o.object_type AND c.authority_release_id=o.allocation_release_id WHERE c.object_type IS NULL OR c.identity_strategy<>o.identity_strategy;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q20_vocab_triggers_installed FROM p3_categorical_field_binding b WHERE NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relname=b.table_name AND NOT t.tgisinternal AND pg_get_triggerdef(t.oid) LIKE '%p3_enforce_vocab_code%');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q21_type_triggers_installed FROM p3_object_reference_type_contract b WHERE NOT EXISTS (SELECT 1 FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relname=b.table_name AND NOT t.tgisinternal AND pg_get_triggerdef(t.oid) LIKE '%p3_enforce_object_reference_type%');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q22_hyperedge_roles_valid FROM p3_hyperedge h JOIN p3_hyperedge_membership m USING(hyperedge_id) LEFT JOIN p3_hyperedge_role_type_contract c ON c.hyperedge_type=h.hyperedge_type AND c.participant_role=m.participant_role AND c.authority_release_id=h.authority_release_id LEFT JOIN p3_object_registry o ON o.object_id=m.object_id WHERE c.hyperedge_type IS NULL OR NOT (o.object_type=ANY(c.allowed_object_types));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q23_pair_count_states FROM p3_candidate_revision r JOIN (SELECT candidate_revision_id,COUNT(*) n FROM p3_internal_pair_matrix GROUP BY 1) x USING(candidate_revision_id) JOIN (SELECT candidate_revision_id,COUNT(*) n FROM p3_candidate_membership WHERE membership_role='PROPOSED_MEMBER' GROUP BY 1) m USING(candidate_revision_id) WHERE x.n<>(m.n*(m.n-1))/2;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q24_latest_pointer_promoted FROM p3_runtime_promotion_pointer p WHERE (SELECT status FROM p3_release_status_event e WHERE e.release_id=p.promoted_release_id ORDER BY event_ordinal DESC LIMIT 1) IS DISTINCT FROM 'PROMOTED';
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q25_hyperedge_cardinality FROM p3_hyperedge h JOIN p3_hyperedge_role_type_contract c ON c.hyperedge_type=h.hyperedge_type AND c.authority_release_id=h.authority_release_id LEFT JOIN (SELECT hyperedge_id,participant_role,COUNT(*) n FROM p3_hyperedge_membership GROUP BY 1,2) m ON m.hyperedge_id=h.hyperedge_id AND m.participant_role=c.participant_role WHERE COALESCE(m.n,0)<c.minimum_count OR (c.maximum_count IS NOT NULL AND COALESCE(m.n,0)>c.maximum_count);

-- Q26-Q34 final bounded-readiness closure.
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q26_identity_values_valid FROM p3_object_registry o JOIN p3_identity_key_contract c ON c.object_type=o.object_type AND c.authority_release_id=o.allocation_release_id WHERE o.identity_strategy<>c.identity_strategy OR (c.id_pattern<>'UPSTREAM_EXACT' AND o.object_id !~ ('^'||c.id_pattern||'$')) OR (o.identity_strategy='CONTENT_ADDRESSED_DERIVED_ID' AND (o.content_hash IS NULL OR split_part(o.object_id,'-',2)<>substr(o.content_hash,1,16)));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q27_candidate_revision_ordinals FROM p3_candidate_revision WHERE candidate_revision_id !~ ('^P3CANDREV-'||substring(candidate_family_id from '[0-9]{6}$')||'-R'||lpad(revision_number::text,4,'0')||'$');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q28_variant_revision_ordinals FROM p3_family_variant_revision WHERE variant_revision_id !~ ('^P3VARREV-'||substring(variant_id from '[0-9]{6}$')||'-R'||lpad(revision_number::text,4,'0')||'$');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q29_status_specific_decisions FROM p3_adjudication_decision a WHERE (a.decision_status='SPLIT_REQUIRED' AND NOT EXISTS (SELECT 1 FROM p3_adjudication_split_point s WHERE s.adjudication_id=a.adjudication_id)) OR (a.decision_status='HIERARCHICAL_RELATION_ONLY' AND NOT EXISTS (SELECT 1 FROM p3_adjudication_hierarchy_relation h WHERE h.adjudication_id=a.adjudication_id)) OR (a.decision_status IN ('BLOCKED_UNRESOLVED','INSUFFICIENT_AUTHORITY') AND NOT EXISTS (SELECT 1 FROM p3_adjudication_unresolved_boundary u WHERE u.adjudication_id=a.adjudication_id)) OR (a.decision_status='ACCEPTED_WITH_VARIANTS' AND NOT EXISTS (SELECT 1 FROM p3_adjudication_member m WHERE m.adjudication_id=a.adjudication_id AND m.variant_revision_id IS NOT NULL));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q30_named_exclusion_shape FROM p3_family_exclusion e WHERE (e.exclusion_type='NAMED_MEMBER' AND NOT EXISTS (SELECT 1 FROM p3_excluded_object x WHERE x.exclusion_id=e.exclusion_id)) OR (e.exclusion_type='RULE_BASED' AND EXISTS (SELECT 1 FROM p3_excluded_object x WHERE x.exclusion_id=e.exclusion_id));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q31_collision_roles FROM p3_collision_scope_registry WHERE (orientation='DIRECTIONAL' AND (left_role IS NULL OR right_role IS NULL OR left_role=right_role)) OR (orientation='SYMMETRIC' AND (left_role IS NOT NULL OR right_role IS NOT NULL));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q32_symmetric_pair_order FROM p3_pair_fact_bundle WHERE orientation='SYMMETRIC' AND left_object_id>=right_object_id;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q33_candidate_revision_has_current_stage FROM p3_candidate_revision r WHERE NOT EXISTS (SELECT 1 FROM p3_candidate_revision_current_stage s WHERE s.candidate_revision_id=r.candidate_revision_id);
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q34_vocabulary_snapshot_complete FROM p3_categorical_field_binding b WHERE NOT EXISTS (SELECT 1 FROM p3_vocabulary_revision v WHERE v.vocabulary_domain=b.vocabulary_domain AND v.authority_release_id=b.authority_release_id AND NOT v.deprecated);

SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q35_split_points_complete FROM p3_adjudication_split_point s WHERE NOT EXISTS (SELECT 1 FROM p3_adjudication_split_member m WHERE m.adjudication_id=s.adjudication_id AND m.split_ordinal=s.split_ordinal AND m.split_side='LEFT') OR NOT EXISTS (SELECT 1 FROM p3_adjudication_split_member m WHERE m.adjudication_id=s.adjudication_id AND m.split_ordinal=s.split_ordinal AND m.split_side='RIGHT') OR EXISTS (SELECT 1 FROM p3_adjudication_split_member l JOIN p3_adjudication_split_member r USING(adjudication_id,split_ordinal,member_object_id) WHERE l.adjudication_id=s.adjudication_id AND l.split_ordinal=s.split_ordinal AND l.split_side='LEFT' AND r.split_side='RIGHT');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q36_lineage_disposition_refs FROM p3_lineage_disposition d WHERE (d.disposition_status='CANONICAL_MEMBER') IS DISTINCT FROM (d.canonical_family_id IS NOT NULL);

-- Q37-Q48 implementation-falsification closure.
SELECT CASE WHEN COUNT(*)=13526 AND SUM(member_n)=18276 THEN 'PASS' ELSE 'FAIL' END AS q37_imported_lineage_membership_counts FROM (SELECT lineage_id,COUNT(*) member_n FROM p3_imported_lineage_membership GROUP BY lineage_id) x;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q38_segment_members_subset FROM p3_lineage_segment_member m JOIN p3_lineage_segment s USING(segment_id) WHERE NOT EXISTS (SELECT 1 FROM p3_imported_lineage_membership i WHERE i.lineage_id=s.parent_lineage_id AND i.implementation_id=m.implementation_id);
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q39_pair_endpoint_resolution_complete FROM p3_pair_fact_bundle p WHERE (SELECT COUNT(*) FROM p3_pair_endpoint_resolution r WHERE r.pair_fact_id=p.pair_fact_id)<>2;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q40_component_edges_reconcile FROM p3_candidate_component c LEFT JOIN (SELECT component_id,COUNT(*) n FROM p3_component_connectivity_edge GROUP BY 1) e USING(component_id) WHERE COALESCE(e.n,0)<>c.connectivity_edge_count;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q41_component_edge_types FROM p3_candidate_component c JOIN p3_component_connectivity_edge e USING(component_id) JOIN p3_pair_projection pr USING(projection_id) JOIN p3_pair_fact_bundle p ON p.pair_fact_id=pr.pair_fact_id WHERE (c.component_type='STRICT_RESPONSE_COMPONENT' AND p.relation_type<>'PROPOSITION_RESPONSE_IDENTITY') OR (c.component_type='PROPOSITION_ONLY_COMPONENT' AND p.relation_type<>'PROPOSITION_IDENTITY_ONLY');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q42_internal_pair_endpoints_are_members FROM p3_internal_pair_matrix x WHERE NOT EXISTS (SELECT 1 FROM p3_candidate_membership m WHERE m.candidate_revision_id=x.candidate_revision_id AND m.member_object_id=x.left_object_id AND m.membership_role='PROPOSED_MEMBER') OR NOT EXISTS (SELECT 1 FROM p3_candidate_membership m WHERE m.candidate_revision_id=x.candidate_revision_id AND m.member_object_id=x.right_object_id AND m.membership_role='PROPOSED_MEMBER');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q43_candidate_event_revision_scope FROM p3_candidate_status_event e JOIN p3_candidate_revision r USING(candidate_revision_id) WHERE e.candidate_family_id<>r.candidate_family_id OR e.authority_release_id<>r.authority_release_id;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q44_signature_subject_types FROM p3_proposition_signature s JOIN p3_object_registry o ON o.object_id=s.subject_id WHERE o.object_type NOT IN ('IMPORTED_SOURCE_LOCAL_LINEAGE','LINEAGE_SEGMENT','CANDIDATE_REVISION','CANONICAL_FAMILY_REVISION');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q45_candidate_membership_prospective_only FROM p3_candidate_membership WHERE membership_role NOT IN ('PROPOSED_MEMBER','PROPOSED_HIERARCHICAL_CONTEXT');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q46_genealogy_cardinality FROM p3_family_genealogy g WHERE (g.relation_type='SPLIT' AND ((SELECT COUNT(*) FROM p3_family_genealogy_member m WHERE m.genealogy_id=g.genealogy_id AND m.genealogy_role='PREDECESSOR')<>1 OR (SELECT COUNT(*) FROM p3_family_genealogy_member m WHERE m.genealogy_id=g.genealogy_id AND m.genealogy_role='SUCCESSOR')<2)) OR (g.relation_type='MERGE' AND ((SELECT COUNT(*) FROM p3_family_genealogy_member m WHERE m.genealogy_id=g.genealogy_id AND m.genealogy_role='PREDECESSOR')<2 OR (SELECT COUNT(*) FROM p3_family_genealogy_member m WHERE m.genealogy_id=g.genealogy_id AND m.genealogy_role='SUCCESSOR')<>1));
SELECT CASE WHEN COUNT(*)=1 THEN 'PASS' ELSE 'FAIL' END AS q47_release_reactivation_transition FROM p3_release_lifecycle_transition WHERE from_status='SUPERSEDED' AND to_status='PROMOTED';
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q48_no_mutable_stage_column FROM information_schema.columns WHERE table_name='p3_candidate_revision' AND column_name='lifecycle_stage';


-- V27 pair-projection and adjudication closure diagnostics.
SELECT pair_fact_id,left_subject_id,right_subject_id,COUNT(*) FROM p3_pair_projection GROUP BY 1,2,3 HAVING COUNT(*)<>1;
SELECT c.candidate_revision_id FROM p3_candidate_revision c LEFT JOIN p3_candidate_membership m USING(candidate_revision_id) GROUP BY 1 HAVING COUNT(m.member_object_id)=0;
SELECT d.adjudication_id FROM p3_adjudication_decision d JOIN p3_candidate_revision r USING(candidate_revision_id) LEFT JOIN p3_adjudication_member m USING(adjudication_id) LEFT JOIN p3_candidate_membership cm ON cm.candidate_revision_id=r.candidate_revision_id AND cm.member_object_id=m.member_object_id GROUP BY d.adjudication_id HAVING COUNT(m.member_object_id)<>COUNT(cm.member_object_id);
SELECT adjudication_id FROM p3_adjudication_split_result_member GROUP BY adjudication_id,member_object_id HAVING COUNT(*)<>1;
SELECT r.family_revision_id FROM p3_canonical_family_revision r LEFT JOIN p3_adjudication_decision d ON d.adjudication_id=r.created_by_adjudication_id WHERE d.adjudication_id IS NULL;


-- V7 executable-closure gates.
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q49_candidate_origin_keys_nonzero FROM p3_candidate_revision WHERE origin_key !~ '^[0-9a-f]{64}$' OR origin_key ~ '^0{64}$';
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q50_candidate_event_times_monotonic FROM p3_candidate_status_event e JOIN p3_candidate_status_event p ON p.candidate_revision_id=e.candidate_revision_id AND p.event_ordinal=e.event_ordinal-1 WHERE e.occurred_at<=p.occurred_at;
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q51_component_projection_types FROM p3_candidate_component c JOIN p3_component_connectivity_edge e USING(component_id) JOIN p3_pair_projection pr USING(projection_id) JOIN p3_pair_fact_bundle pf ON pf.pair_fact_id=pr.pair_fact_id WHERE (c.component_type='STRICT_RESPONSE_COMPONENT' AND pf.relation_type<>'PROPOSITION_RESPONSE_IDENTITY') OR (c.component_type='PROPOSITION_ONLY_COMPONENT' AND pf.relation_type<>'PROPOSITION_IDENTITY_ONLY');
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q52_direct_pairs_use_projection FROM p3_internal_pair_matrix x LEFT JOIN p3_pair_projection pr ON pr.projection_id=x.direct_pair_projection_id WHERE x.pair_state IN ('DIRECT_POSITIVE','DIRECT_COLLISION','DIRECT_UNRESOLVED','HIERARCHICAL_ONLY') AND (pr.projection_id IS NULL OR NOT ((pr.left_subject_id=x.left_object_id AND pr.right_subject_id=x.right_object_id) OR (pr.left_subject_id=x.right_object_id AND pr.right_subject_id=x.left_object_id)));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q53_split_dispositions_match_results FROM p3_adjudication_decision d JOIN p3_adjudication_member m USING(adjudication_id) WHERE d.decision_status='SPLIT_REQUIRED' AND (m.member_disposition<>'SPLIT' OR NOT EXISTS (SELECT 1 FROM p3_adjudication_split_result_member r WHERE r.adjudication_id=d.adjudication_id AND r.member_object_id=m.member_object_id));
SELECT CASE WHEN COUNT(*)=0 THEN 'PASS' ELSE 'FAIL' END AS q54_assertion_triggers_installed WHERE NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='p3_candidate_origin_revision_closure') OR NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='p3_adjudication_partition_decision_closure');
